pub struct Observed {pub result:Result<(),u8>,pub events:[u8;7],pub len:usize}
fn event(o:&mut Observed,tag:u8){o.events[o.len]=tag;o.len+=1;}
pub fn finish_ref(two:bool,next:usize,rhs:Word,r:Replies)->Observed {
