struct PrefixLog{reply:[[K;10];3],arg:[K;10],ptr:*const K,calls:usize}
fn point_call(alpha:&[K;10],log:&mut PrefixLog)->[[K;10];3]{log.arg=*alpha;log.ptr=alpha.as_ptr();log.calls+=1;log.reply}
